# Add comments to each step of your logic

def numberOfPairs(nums1, nums2, queries):
    n = len(nums2)
    B = 256                      # block size for sqrt decomposition
    nb = (n + B - 1) // B        # number of blocks

    # Distinct values of nums1 with multiplicity (at most 5 entries)
    mult = {}
    for v in nums1:
        mult[v] = mult.get(v, 0) + 1
    vals = list(mult.items())

    a = nums2[:]                 # stored values; real value = a[i] + lazy[block of i]
    lazy = [0] * nb
    cnt = []                     # cnt[b][value] = number of elements in block b with that stored value
    for b in range(nb):
        d = {}
        for i in range(b * B, min(n, (b + 1) * B)):
            d[a[i]] = d.get(a[i], 0) + 1
        cnt.append(d)

    def partial(b, l, r, val):
        # Update elements l..r of block b one at a time
        d = cnt[b]
        for i in range(l, r + 1):
            old = a[i]
            if d[old] == 1:
                del d[old]
            else:
                d[old] -= 1
            new = old + val
            a[i] = new
            d[new] = d.get(new, 0) + 1

    def apply(b, l, r, val):
        # If the range covers the whole block use the lazy tag, else update elements
        start = b * B
        end = min(n, start + B) - 1
        if l == start and r == end:
            lazy[b] += val
        else:
            partial(b, l, r, val)

    answer = []
    for q in queries:
        if q[0] == 1:
            x, y, val = q[1], q[2], q[3]
            bx = x // B
            by = y // B
            if bx == by:
                apply(bx, x, y, val)
            else:
                # Left partial block, full blocks in the middle, right partial block
                apply(bx, x, (bx + 1) * B - 1, val)
                for b in range(bx + 1, by):
                    lazy[b] += val
                apply(by, by * B, y, val)
        else:
            tot = q[1]
            total = 0
            for b in range(nb):
                d = cnt[b]
                need = tot - lazy[b]          # stored value + v must equal this
                for v, mu in vals:
                    c = d.get(need - v)
                    if c:
                        total += mu * c
            answer.append(total)

    return answer
